1	package importer
2	
3	import (
4		"encoding/csv"
5		"errors"
6		"fmt"
7		"io"
8		"strconv"
9		"strings"
10	)
11	
12	// Row is one stock line from an import file.
13	type Row struct {
14		Name     string
15		Quantity int
16		Unit     string
17	}
18	
19	// RowError reports a malformed row by its 1-based line number.
20	type RowError struct {
21		Line int
22		Err  error
23	}
24	
25	func (e RowError) Error() string { return fmt.Sprintf("line %d: %v", e.Line, e.Err) }
26	
27	// ReadStock parses `name,quantity,unit` rows. Malformed rows are skipped and returned as errors.
28	func ReadStock(r io.Reader) ([]Row, []RowError, error) {
29		reader := csv.NewReader(r)
30		reader.FieldsPerRecord = -1
31	
32		var rows []Row
33		var bad []RowError
34	
35		for line := 1; ; line++ {
36			record, err := reader.Read()
37			if errors.Is(err, io.EOF) {
38				return rows, bad, nil
39			}
40			if err != nil {
41				return nil, nil, fmt.Errorf("reading stock csv: %w", err)
42			}
43			if len(record) != 3 {
44				bad = append(bad, RowError{Line: line, Err: fmt.Errorf("want 3 fields, got %d", len(record))})
45				continue
46			}
47			qty, err := strconv.Atoi(strings.TrimSpace(record[1]))
48			if err != nil {
49				bad = append(bad, RowError{Line: line, Err: fmt.Errorf("quantity %q: %w", record[1], err)})
50				continue
51			}
52			rows = append(rows, Row{Name: strings.TrimSpace(record[0]), Quantity: qty, Unit: strings.TrimSpace(record[2])})
53		}
54	}
